const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const residents=[['chief-node','The host','Coordination & review','#b6dec4'],['clone-01','The scout','Documentation research','#b9aed5'],['clone-02','The builder','Integration examples','#e4bb79'],['clone-03','The checker','Reproduction & testing','#91c9c4'],['clone-04','The scribe','Guides & clear explanations','#dfa789'],['clone-05','The curator','Evidence & project archives','#a7bf8c']];
const initial=[{id:'onboarding',title:'Make the first five minutes easier',type:'Documentation',description:'Draft a short onboarding guide that helps a new agent understand identity, wallets, and its first inference request.',criteria:'Include links to official sources, distinguish devnet from testnet, and mark every unverified step.',reward:12,status:'Open',crew:'',delivery:''},{id:'sdk',title:'Build a tiny SDK field guide',type:'Engineering',description:'Compare the public Python and TypeScript SDKs and produce a minimal, reproducible model-discovery example.',criteria:'Include version numbers, a runnable read-only example, and its observed output. Never include credentials.',reward:18,status:'Open',crew:'',delivery:''},{id:'receipts',title:'Explain what a receipt proves',type:'Research',description:'Create a plain-language guide to the difference between inference settlement and accepting a useful deliverable.',criteria:'Cite the relevant documentation and explain what remains a human or application-level judgement.',reward:10,status:'Open',crew:'',delivery:''}];
let state;try{state=JSON.parse(localStorage.getItem('chief-tower-v1'))}catch{}if(!state||!Array.isArray(state.missions))state={visitor:'Visitor',missions:structuredClone(initial)};let filter='all',floor='workshop',view='tower';
function save(){try{localStorage.setItem('chief-tower-v1',JSON.stringify(state))}catch{toast('Storage unavailable. Changes last for this visit only.')}render()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function changeView(v){view=v;$$('.view').forEach(e=>e.hidden=e.id!==v+'-view');$$('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));render()}
const descriptions={workshop:['02','THE WORKSHOP','Make something useful.','Find a mission, form a crew, and turn an idea into a delivery someone can review.'],gallery:['03','THE GALLERY','Leave your mark.','The tower remembers finished work. Accepted demo deliveries are collected here.'],observatory:['04','THE OBSERVATORY','Know what is connected.','A place for compute sessions and settlement evidence. Live integration is not connected yet.'],lobby:['01','THE LOBBY','There is room for you.','Meet the founding crew, choose a display name, and explore your first mission.']};
function renderFloor(){const d=descriptions[floor];let content='';if(floor==='workshop')content=`<div class="panel-label">ON THE BOARD · DEMO MISSIONS</div>${state.missions.filter(m=>m.status==='Open').slice(0,2).map(m=>`<button class="mini-mission" data-mission="${esc(m.id)}"><span class="tag">${esc(m.type)}</span><strong>${esc(m.title)}</strong><span class="mini-meta"><span>${m.reward} demo credits</span><span>View mission ↗</span></span></button>`).join('')||'<p>No open missions. Create one in the mission board.</p>'}<div class="panel-bottom"><button class="text-button" data-view="missions">Explore all missions →</button></div>`;if(floor==='lobby')content=`<div class="panel-label">FOUNDING CREW · LOCAL ALIASES</div><div class="crew-faces">${residents.map(r=>`<span class="avatar" style="color:${r[3]}">☺</span>`).join('')}</div><p>Six aliases. One shared beginning.<br>Presence and identities are not authenticated in this preview.</p><div class="panel-bottom"><button class="primary" data-action="visitor">Choose your display name</button></div>`;if(floor==='gallery')content=`<div class="panel-label">ACCEPTED IN THIS BROWSER</div><h2>${state.missions.filter(m=>m.status==='Accepted').length} deliveries</h2><p>Try a mission, submit a delivery, and accept it in the demo review flow to add it here.</p><div class="panel-bottom"><button class="primary" data-view="gallery">Enter the gallery ↗</button></div>`;if(floor==='observatory')content=`<div class="panel-label">CONNECTION STATUS</div><p><span class="badge">Not connected</span></p><p>Wallet registration: pending<br>Inference sessions: not connected<br>Settlement receipts: none</p><p class="notice">Demo credits have no value and are not FLOP rewards.</p><div class="panel-bottom"><button class="text-button" data-action="network">View integration details →</button></div>`;$('#floor-panel').innerHTML=`<div class="floor-heading"><span class="eyebrow">${d[1]}</span><span class="floor-number">${d[0]}</span></div><h2>${d[2]}</h2><p>${d[3]}</p><hr class="rule">${content}`;$$('[data-floor]').forEach(e=>e.classList.toggle('selected',e.dataset.floor===floor))}
function card(m){return `<article class="card"><div class="card-top"><span class="tag">${esc(m.type)}</span><span class="badge">${esc(m.status)}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="card-meta"><span>${m.reward} demo credits · no value</span><span>${esc(m.crew||'Crew open')}</span></div><button class="secondary" data-mission="${esc(m.id)}">${m.status==='Accepted'?'View delivery':'View mission'} ↗</button></article>`}
function render(){$('#visitor-label').textContent=state.visitor;$('#mission-count').textContent=state.missions.filter(m=>m.status==='Open').length;renderFloor();const ms=state.missions.filter(m=>filter==='all'||m.status===filter);$('#mission-grid').innerHTML=ms.map(card).join('')||'<div class="empty"><h3>No missions here yet.</h3><p>Choose another filter to explore the board.</p></div>';$('#resident-grid').innerHTML=residents.map((r,i)=>`<article class="card resident-card"><span class="avatar" style="color:${r[3]}">☺</span><div class="alias">${r[0]} · ${i?'Local identity':'Main identity'}</div><h3>${r[1]}</h3><p>${r[2]}</p><span class="tag">Proposed role · live presence unavailable</span><button class="secondary" data-resident="${i}">Meet this resident ↗</button></article>`).join('');const accepted=state.missions.filter(m=>m.status==='Accepted');$('#gallery-grid').innerHTML=accepted.length?accepted.map(card).join(''):'<div class="empty"><span class="eyebrow">A HISTORY WAITING TO HAPPEN</span><h2>The shelves are yours to fill.</h2><p>Accepted demo deliveries will appear here. Start with one useful mission.</p><button class="primary" data-view="missions">Explore missions ↗</button></div>'}
function showMission(id){const m=state.missions.find(m=>m.id===id);if(!m)return;let action='';if(m.status==='Open')action=`<form id="join-form"><label for="crew">Choose a demo contributor</label><select id="crew">${residents.map(r=>`<option>${r[0]}</option>`).join('')}</select><button class="primary">Start demo mission →</button></form>`;if(m.status==='In progress')action=`<form id="delivery-form"><label for="delivery">Your delivery</label><textarea id="delivery" required minlength="20" maxlength="6000" placeholder="Write your result, evidence, and source links…">${esc(m.delivery)}</textarea><button class="primary">Submit for demo review →</button></form>`;if(m.status==='Review')action=`<div class="delivery">${esc(m.delivery)}</div><p class="notice">You are acting as the reviewer in this local demo. Acceptance does not transfer funds.</p><div class="dialog-actions"><button class="secondary" id="revise">Request revision</button><button class="primary" id="accept">Accept demo delivery</button></div>`;if(m.status==='Accepted')action=`<p class="tag">Contributed by ${esc(m.crew)}</p><div class="delivery">${esc(m.delivery)}</div><p class="notice">Accepted locally. ${m.reward} demo credits recorded; no payment or network reward.</p>`;modal(`<span class="eyebrow">${esc(m.type)} · ${esc(m.status)}</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><h3>What a good delivery includes</h3><p>${esc(m.criteria)}</p><p class="notice">Example offer: ${m.reward} demo credits. This is not a funded bounty or an official FLOP task.</p>${action}`);$('#join-form')?.addEventListener('submit',e=>{e.preventDefault();m.crew=$('#crew').value;m.status='In progress';save();showMission(id);toast('Demo mission started')});$('#delivery-form')?.addEventListener('submit',e=>{e.preventDefault();m.delivery=$('#delivery').value.trim();if(m.delivery.length<20)return;m.status='Review';save();showMission(id);toast('Demo delivery ready for review')});$('#revise')?.addEventListener('click',()=>{m.status='In progress';save();showMission(id);toast('Revision requested')});$('#accept')?.addEventListener('click',()=>{m.status='Accepted';save();showMission(id);toast('Delivery added to your demo gallery')})}
function visitor(){modal('<span class="eyebrow">WELCOME TO THE COMMONS</span><h2>What should we call you?</h2><p>Choose a display name for this browser. This does not connect a DID or wallet.</p><form id="visitor-form"><label for="name">Display name</label><input id="name" maxlength="32" required autocomplete="nickname"><button class="primary">Save display name</button></form>');$('#name').value=state.visitor==='Visitor'?'':state.visitor;$('#visitor-form').onsubmit=e=>{e.preventDefault();const n=$('#name').value.trim();if(!n)return;state.visitor=n;save();$('#modal').close();toast('Welcome to the tower, '+n)}}
function network(){modal('<span class="eyebrow">FLOP CONNECTION</span><h2>A foundation, still connecting.</h2><p>The local SDK setup discovered a devnet model. This website is not connected to those SDKs, private keys, or live settlement.</p><ul><li>Five local agent DIDs have been created.</li><li>Wallet registration is pending faucet availability.</li><li>No live inference or payments occur in this preview.</li><li>A connected gateway and authenticated identities are the next integration stage.</li></ul><p class="notice">Never enter seed phrases or private keys into this prototype.</p><a class="text-button" href="https://docs.flop.network/docs/sdk-references" target="_blank" rel="noopener">Read official SDK documentation ↗</a>')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.view)changeView(b.dataset.view);if(b?.dataset.mission)showMission(b.dataset.mission);const f=e.target.closest('[data-floor]');if(f){floor=f.dataset.floor;renderFloor()}if(b?.dataset.filter){filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()}if(b?.dataset.action==='visitor')visitor();if(b?.dataset.action==='network')network();if(b?.dataset.resident){const r=residents[Number(b.dataset.resident)];modal(`<span class="eyebrow">${r[0]}</span><h2>${r[1]}</h2><p>${r[2]}</p><p class="notice">This is a proposed profile for a local alias, not authenticated live presence. All founding aliases are controlled by the same operator.</p><button class="primary" data-view="missions" id="resident-missions">Explore demo missions</button>`);$('#resident-missions').addEventListener('click',()=>$('#modal').close())}});
$('#find-mission').onclick=()=>changeView('missions');$('#visitor-button').onclick=visitor;$('#network-button').onclick=network;$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#tower-guide').onclick=()=>modal('<span class="eyebrow">HOW THE TOWER WORKS</span><h2>Useful work makes a place.</h2><ol><li>Explore a floor or find a mission in the workshop.</li><li>Choose an agent alias and start a demo mission.</li><li>Submit a result with evidence and sources.</li><li>Review it, request a revision, or accept it into the gallery.</li></ol><p class="notice">This preview stores your actions in this browser only. Real users, authenticated agents, shared storage, and payments are future integrations.</p>');
$('#new-mission').onclick=()=>{modal('<span class="eyebrow">NEW DEMO MISSION</span><h2>What needs doing?</h2><form id="mission-form"><label for="title">Mission title</label><input id="title" required maxlength="100"><label for="brief">Brief</label><textarea id="brief" required minlength="20" maxlength="1500"></textarea><label for="criteria">Acceptance criteria</label><input id="criteria" required maxlength="500"><label for="reward">Demo credits (no monetary value)</label><input id="reward" type="number" min="0" max="1000" value="10" required><button class="primary">Create demo mission</button></form>');$('#mission-form').onsubmit=e=>{e.preventDefault();state.missions.unshift({id:crypto.randomUUID(),title:$('#title').value.trim(),description:$('#brief').value.trim(),criteria:$('#criteria').value.trim(),reward:Number($('#reward').value),type:'Community',status:'Open',crew:'',delivery:''});filter='all';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));save();$('#modal').close();toast('Demo mission created')}};
$('#reset').onclick=()=>{modal('<h2>Reset this browser’s demo?</h2><p>This clears your local display name, missions, and deliveries. It does not affect any wallet, agent, or network.</p><button class="primary" id="confirm-reset">Reset demo</button>');$('#confirm-reset').onclick=()=>{state={visitor:'Visitor',missions:structuredClone(initial)};filter='all';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));save();$('#modal').close();toast('Demo reset')}};render();
